def first_decimal_is_a_number(epsilon: float, x: int) -> bool:
    """ Given two positive floating point numbers, this function return whether
    the first decimal of number x (after truncating) is a non-zero integer.

    >>> first_decimal_is_a_number(0.01, 5.009)
    False
    >>> first_decimal_is_a_number(0.01, 6.001)
    True
    """
    if truncate_number(x) == 0.0:
        return False
    if epsilon == 0:
        return True
    else:
        number_of_digits = trunc(log10(epsilon))
        return trunc(x * (10 ** number_of_digits)) % 10 != 0

