def find_maximum_depth_in_string(paren_string: str) -> int:
    """ Given a string of parentheses, find the maximum depth of nesting. """

    stack = []
    max_depth = 0

    for c in paren_string:
        if c == "(":
            stack.append(c)
            max_depth = max(max_depth, len(stack))
        if c == ")":
            stack.pop()

    return max_depth

