def _parse_nested_parens(paren_group: str):
    """ Utility function which handles a single group of parentheses.
    """
    opened = []
    closed = []
    for index, parentheses in enumerate(paren_group):
        if parentheses == '(':
            opened.append(index)
        elif parentheses == ')':
            closed.append(index)

    return [i - j if i < j else None for i, j in zip(opened, reversed(closed))]


